package net.nuggetmc.tplus.compat.bukkit.craftbukkit;
import net.nuggetmc.tplus.compat.bukkit.inventory.EquipmentSlot;
public final class CraftEquipmentSlot { private CraftEquipmentSlot(){} public static net.minecraft.world.entity.EquipmentSlot getNMS(EquipmentSlot slot){return slot==null?net.minecraft.world.entity.EquipmentSlot.MAINHAND:slot.nms();} public static EquipmentSlot getSlot(net.minecraft.world.entity.EquipmentSlot slot){return switch(slot){case MAINHAND->EquipmentSlot.HAND;case OFFHAND->EquipmentSlot.OFF_HAND;case FEET->EquipmentSlot.FEET;case LEGS->EquipmentSlot.LEGS;case CHEST->EquipmentSlot.CHEST;case HEAD->EquipmentSlot.HEAD;};} }
